// 1. Global (Namespace) Scope
static int global_data = 100;
static int global_bss; // Initialized to 0

// 2. Class Scope (Declaration)
class Singleton {
    static const int MAX_SIZE = 10;
    static double instance_count;
};

// 3. Class Scope (Definition/Initialization outside class)
const int Singleton::MAX_SIZE; // Implicitly initialized at link time
double Singleton::instance_count = 0.0; // Zero initialization (data segment)

// 4. Function Scope (Local Statics)
void foo() {
    // Initialized on first call (thread safe since C++11)
    static long counter = expensive_setup();
}
